const filters=document.querySelectorAll('[data-filter]'),search=document.querySelector('#search'),sort=document.querySelector('#sort'),grid=document.querySelector('.archive .project-grid');const cards=[...document.querySelectorAll('.archive .project')];let category='all';function filter(){let n=0;cards.forEach(c=>{const show=(category==='all'||c.dataset.category===category)&&c.dataset.name.includes((search?.value||'').toLowerCase().trim());c.hidden=!show;if(show){n++;c.classList.remove('waiting')}});const count=document.querySelector('#result-count');if(count)count.textContent=`${n} PROJECT${n===1?'':'S'}`;const empty=document.querySelector('#empty');if(empty)empty.hidden=n>0}filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filters.forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'));filter()}));search?.addEventListener('input',filter);sort?.addEventListener('change',()=>{const list=[...cards];if(sort.value!=='featured')list.sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name)*(sort.value==='za'?-1:1));list.forEach(c=>grid.append(c));filter()});const box=document.querySelector('#lightbox');let opener;document.querySelectorAll('.image-open').forEach(b=>b.addEventListener('click',()=>{opener=b;const source=b.querySelector('img');box.querySelector('img').src=source.src;box.querySelector('img').alt=source.alt;box.querySelector('p').textContent=b.dataset.caption;box.showModal();document.body.style.overflow='hidden'}));function closed(){document.body.style.overflow='';opener?.focus()}box?.querySelector('button').addEventListener('click',()=>box.close());box?.addEventListener('close',closed);box?.addEventListener('click',e=>{if(e.target===box)box.close()});document.querySelector('#brief')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const text=`Hello Odusina Isaac, I would like to discuss a design project.\n\nName: ${d.get('name')}\nBrand: ${d.get('brand')}\nService: ${d.get('service')}\nBudget: ${d.get('budget')||'To discuss'}\nTimeline: ${d.get('timeline')||'To discuss'}\n\n${d.get('message')}`;window.location.href='https://wa.me/2348061688292?text='+encodeURIComponent(text)});if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const io=new IntersectionObserver(items=>items.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('waiting');io.unobserve(e.target)}}),{threshold:0,rootMargin:'0px 0px 80px 0px'});document.querySelectorAll('.reveal').forEach(e=>{if(e.getBoundingClientRect().top>innerHeight+100){e.classList.add('waiting');io.observe(e)}})}
